#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    const long long MOD = 1000000007;
    long long two = 1, one = (s[0] != '0') ? 1 : 0;
    for (size_t i = 1; i < s.size(); i++) {
        long long cur = 0;
        if (s[i] != '0') cur += one;
        int pair = (s[i - 1] - '0') * 10 + (s[i] - '0');
        if (pair >= 10 && pair <= 26) cur += two;
        two = one;
        one = cur % MOD;
    }
    cout << one % MOD << "\n";

    return 0;
}

